capture() {
  if (this.closed) return
  const now = this.clock().toISOString()
  for (const record of operationSources(this.store, now)) {
    if (this.store.database.prepare('SELECT 1 FROM operation_events WHERE id=?').get(record.id)) continue
    this.store.transaction(() => {
      for (const row of this.store.database.prepare('SELECT record_json FROM operation_events').all()) {
        const previous = dto.operationRowSchema.parse(JSON.parse(String(row.record_json)))
        if (previous.current && previous.owner.domain === record.owner.domain && previous.owner.id === record.owner.id)
          this.store.database.prepare('UPDATE operation_events SET record_json=? WHERE id=?').run(JSON.stringify({...previous,current:false,recoveredAt:now}),previous.id)
      }
      this.store.database.prepare('INSERT INTO operation_events VALUES(?,?)').run(record.id,JSON.stringify(dto.operationRowSchema.parse(record)))
    })
    this.emit(record.owner)
  }
}
